import {lessons,blueprint} from './content.js';
const q=(id,lesson,type,title,prompt,answer,rubric,pitfall,resource=null)=>({id,lesson,type,title,prompt,answer,rubric,pitfall,resource});
export const questions=[
q('g1','goals','서술','네 목표를 사례에 적용하기','① 도청자가 문서를 읽지 못하게 한다. ② 문서의 변경 여부를 검증한다. ③ 통신 상대의 신원을 확인한다. ④ 계약한 사람이 계약 사실을 부인하지 못하게 한다. 각각의 보안 목표를 쓰고 ②와 ③의 차이를 설명하시오.','① 기밀성 ② 무결성 ③ 인증 ④ 부인방지. 무결성은 데이터가 변경되었는지, 인증은 상대나 메시지의 근원이 누구인지를 다룬다.',['네 목표를 순서대로 정확히 대응했다.','무결성과 인증의 대상을 구별했다.'],'인증·부인방지의 역할과 가용성의 의미를 혼동하지 않는다.'),
q('g2','goals','서술','MAC과 부인방지','MAC이 무결성과 메시지 근원 인증을 제공하면서도 제3자에 대한 부인방지는 제공하지 못하는 이유를 설명하시오.','송수신자는 같은 비밀키를 공유한다. 키 없는 외부인은 유효한 태그를 만들기 어렵고, 수신자는 다시 계산하여 변경과 출처를 확인한다. 하지만 수신자 자신도 태그를 만들 수 있으므로 제3자가 특정 송신자만의 행위라고 판정할 근거가 되지 않는다.',['공유 비밀키를 언급했다.','무결성·메시지 근원 인증을 설명했다.','수신자도 태그를 만들 수 있다는 한계를 썼다.'],'인증과 부인방지를 같은 말로 쓰지 않는다.'),
q('g3','goals','서술','알고리즘 공개와 안전성','Kerckhoffs 원칙을 설명하고, Dₖ(Eₖ(m))=m이 암호시스템에 필요한 이유를 쓰시오.','알고리즘과 구조는 공개되어 있다고 가정하고 키의 비밀성에 안전성을 의존해야 한다. 복호화가 모든 유효 평문에 대해 원문을 복원해야 하므로 Dₖ(Eₖ(m))=m이어야 하며, 고정 키에서 서로 다른 평문이 동일 암호문으로 합쳐지면 이 조건을 만족할 수 없다.',['알고리즘 공개·키 비밀을 구별했다.','정확한 복원 조건을 설명했다.','고정 키 암호화가 단사여야 함을 연결했다.'],'복호화가 가능하다는 조건과 안전하다는 조건은 다르다.'),
q('c1','classical','구별','네 공격 모델','암호문만 관찰하는 경우, 이미 알려진 평문·암호문 쌍을 가진 경우, 원하는 평문을 암호화해 달라고 할 수 있는 경우, 선택한 암호문의 복호화 결과를 얻는 경우의 공격 모델을 각각 쓰시오.','순서대로 암호문 단독 공격(COA), 기지 평문 공격(KPA), 선택 평문 공격(CPA), 선택 암호문 공격(CCA)이다. KPA는 주어진 쌍을 알고 있고 CPA는 평문을 직접 선택하는 권한이 있다는 점이 다르다.',['COA와 KPA를 정확히 대응했다.','CPA와 CCA를 정확히 대응했다.','알고 있음과 선택 권한을 구별했다.'],'공격 모델의 이름은 공격 성공 여부가 아니다.'),
q('c2','classical','서술','큰 키 공간만으로 충분한가','단일 치환 암호는 키가 26!개다. 그럼에도 자연어 메시지를 보호하기에 충분하지 않은 이유를 전수조사와 통계적 특성으로 구분하여 설명하시오.','26!개의 키 공간은 단순 전수조사를 어렵게 하지만, 같은 평문 문자가 항상 같은 암호문 문자로 바뀌므로 문자 빈도와 언어 패턴이 남는다. 이러한 구조적 정보가 안전성을 약화시킨다. 키 공간의 크기는 전수조사에 대한 한 조건이지 전체 안전성의 보증이 아니다.',['큰 키 공간이 전수조사를 어렵게 함을 썼다.','고정 치환이 통계 정보를 남긴다고 설명했다.','전수조사와 구조적 안전성을 구분했다.'],'“키 공간이 크므로 모든 공격에 안전하다”는 결론을 피한다.'),
q('c3','classical','계산','Affine 복호화','a=0,…,z=25로 두고 c=5p+3 mod 26인 Affine 암호를 사용한다. 5의 곱셈 역원과 복호화식을 구한 뒤 c=12를 복호화하시오.','5×21=105≡1 mod 26이므로 역원은 21이다. p=21(c−3) mod 26. c=12일 때 p=189 mod 26=7이며 문자는 h이다.',['역원 21과 검산식을 썼다.','복호화식 21(c−3) mod 26을 썼다.','p=7, h를 얻었다.'],'역원을 곱하기 전에 b를 빼야 한다.'),
q('c4','classical','계산','유효한 Affine 키','c=ap+b mod 26에서 a=2를 키로 쓰면 왜 문제가 되는가? 유효한 (a,b) 키의 총 개수도 구하시오.','gcd(2,26)=2이므로 2에 곱셈 역원이 없다. 예를 들어 p=0과 p=13은 같은 c=b를 만들어 유일한 복호화가 불가능하다. 26과 서로소인 a는 φ(26)=12개, b는 26개이므로 유효 키는 312개이다.',['서로소/역원 조건을 썼다.','단사성 실패 또는 반례를 제시했다.','12×26=312를 계산했다.'],'a를 무조건 26가지로 세면 안 된다.'),
q('c5','classical','비교','Vigenère와 전치','Vigenère 암호에서 반복되는 키의 주기가 중요한 이유와 전치 암호에서 문자 빈도가 보존되는 이유를 설명하시오.','Vigenère는 주기 m의 키를 반복하므로 동일한 키 위치에 해당하는 문자들 사이에 일정한 치환 관계가 반복된다. 주기를 파악하면 위치별 통계적 특성이 드러난다. 전치는 문자 값을 바꾸지 않고 위치만 옮기므로 전체 문자 빈도가 보존된다.',['반복 키와 위치별 관계를 연결했다.','전치가 값 대신 위치를 바꾼다고 썼다.','문자 빈도 보존을 설명했다.'],'Vigenère를 단일 치환과 완전히 동일하다고 쓰지 않는다.'),
q('c6','classical','계산','전수조사량의 의미','균일한 40비트 키를 사용하는 교육용 암호가 있다. 후보 수와 평균 검사 수를 쓰고, 초당 2²⁰개 키를 검사할 때 평균 시간과 이 계산의 전제를 설명하시오.','후보 수는 2⁴⁰개, 평균 검사 수는 약 2³⁹개이다. 평균 시간은 2³⁹/2²⁰=2¹⁹초이다. 정답 키가 균일하고 중복 없이 검사하며 올바른 후보를 판별할 수 있다는 전제가 필요하다.',['후보 2⁴⁰과 평균 2³⁹를 구별했다.','평균 2¹⁹초를 계산했다.','정답 후보 판별 가능성과 균일한 키를 언급했다.'],'평균값과 최악의 경우를 섞지 않는다.'),
q('a1','algebra','증명','Zₙ의 덧셈은 군인가','(Zₙ, + mod n)이 가환군임을 닫힘, 결합법칙, 항등원, 역원, 교환법칙을 이용해 설명하시오.','합을 mod n으로 줄이면 다시 Zₙ에 속한다. 정수 덧셈의 결합·교환법칙이 나머지 연산에서도 유지된다. 0이 항등원이고 a의 역원은 −a mod n이다. 모든 군 조건과 교환법칙을 만족하므로 가환군이다.',['닫힘과 결합법칙을 설명했다.','항등원 0과 덧셈 역원 −a mod n을 썼다.','교환법칙과 가환군 결론을 썼다.'],'곱셈 역원의 조건을 덧셈 역원에 잘못 적용하지 않는다.'),
q('a2','algebra','판별','Z₆와 Z₅의 차이','모듈러 덧셈과 곱셈을 사용한다. Z₆와 Z₅가 각각 환인지 체인지 판별하고, 체가 아닌 경우 반례를 쓰시오.','둘 다 가환환이다. Z₆는 2의 곱셈 역원이 없고 2×3≡0인 영인수가 있으므로 체가 아니다. Z₅에서는 0이 아닌 1,2,3,4가 각각 1,3,2,4를 역원으로 가지므로 체이다.',['둘 다 환임을 썼다.','Z₆의 역원 부재 또는 영인수 반례를 썼다.','Z₅의 비영 원소 역원을 근거로 체라 판별했다.'],'0에 곱셈 역원이 없다는 사실은 모든 체에 해당하므로 반례가 아니다.'),
q('a3','algebra','증명','곱셈 역원과 gcd','Zₙ에서 a에 곱셈 역원이 존재할 필요충분조건이 gcd(a,n)=1임을 설명하시오. EEA 표 전체를 계산할 필요는 없다.','gcd(a,n)=1이면 Bézout 등식 sa+tn=1이 있어 sa≡1 mod n이므로 s가 역원이다. 역으로 ab≡1이면 ab−qn=1이다. a와 n의 공약수는 좌변과 1을 모두 나누어야 하므로 최대공약수는 1이다.',['Bézout 등식에서 역원 존재를 보였다.','역원 존재에서 공약수가 1임을 보였다.'],'한 방향만 보이고 필요충분조건을 증명했다고 하지 않는다.'),
q('a4','algebra','계산','두 종류의 역원','Z₁₈에서 5의 덧셈 역원과 곱셈 역원을 각각 구하고 검산하시오. 6의 곱셈 역원이 있는지도 판단하시오.','5의 덧셈 역원은 13: 5+13≡0. 곱셈 역원은 11: 5×11=55≡1. gcd(6,18)=6이므로 6의 곱셈 역원은 없다.',['덧셈 역원 13을 검산했다.','곱셈 역원 11을 검산했다.','6의 역원이 없음을 gcd로 설명했다.'],'덧셈 항등원은 0, 곱셈 항등원은 1이다.'),
q('a5','algebra','판별','정수는 왜 체가 아닌가','(Z,+,×)와 (Q,+,×)의 구조를 비교하시오. 군과 환을 정의할 때 어떤 연산을 말하는지 명시하시오.','Z와 Q 모두 덧셈에 대해 가환군이고 곱셈의 닫힘·결합법칙·분배법칙이 성립해 가환환이다. Z는 2의 곱셈 역원 1/2가 집합 밖이어서 체가 아니다. Q는 0이 아닌 모든 a에 대해 1/a가 유리수이므로 체이다.',['덧셈 군과 두 연산의 환을 구별했다.','Z의 반례 2를 제시했다.','Q의 비영 원소 역원이 집합 안에 있음을 설명했다.'],'집합 이름만으로 군이라고 하지 말고 연산을 지정한다.'),
q('a6','algebra','계산','부분군과 생성원','(Z₆,+ mod 6)에서 2의 위수와 2가 생성하는 부분군을 구하시오. Z₃를 mod 3 덧셈 그대로 이 군의 부분군이라고 할 수 있는지도 설명하시오.','2,4,0으로 돌아오므로 2의 위수는 3이고 생성 부분군은 {0,2,4}이다. Z₃의 mod 3 덧셈은 mod 6 덧셈과 다르므로 그 연산 그대로 부분군이라 할 수 없다. 예를 들어 2+2는 mod 3에서 1, mod 6에서 4이다.',['위수 3과 {0,2,4}를 구했다.','부분군은 같은 연산이어야 함을 설명했다.','두 mod 연산의 차이를 제시했다.'],'동형인 군이라는 말과 부분군이라는 말을 구분한다.'),
q('f1','gf','계산','비트열과 다항식','0x57을 GF(2) 계수의 다항식으로 나타내고, 0x57+0x83을 GF(2⁸)에서 계산하시오.','0x57=01010111₂=x⁶+x⁴+x²+x+1이다. 덧셈은 XOR이므로 0x57⊕0x83=0xd4이다. 계수를 mod 2로 계산해 동일한 항이 두 번 나오면 소거되기 때문이다.',['비트열·다항식을 바르게 변환했다.','XOR 결과 d4를 얻었다.','계수 mod 2의 이유를 썼다.'],'일반 정수 덧셈의 올림을 사용하지 않는다.'),
q('f2','gf','계산','작은 유한체의 곱셈','GF(2³), m(x)=x³+x+1에서 (x²+1)(x+1)을 계산하시오. 다항식 전개와 나머지 과정을 쓰시오.','전개하면 x³+x²+x+1이다. m(x)=0이므로 x³≡x+1이다. 이를 대입하고 같은 항을 XOR로 소거하면 x²가 남는다. 3비트 표현은 100이다.',['다항식을 정확히 전개했다.','x³≡x+1로 줄였다.','결과 x², 100을 얻었다.'],'다른 기약다항식을 임의로 사용하지 않는다.'),
q('f3','gf','판별','GF(2⁸)과 Z₂₅₆','GF(2⁸)과 Z₂₅₆은 모두 원소가 256개다. 같은 대수 구조라고 할 수 있는가? 이유를 설명하시오.','같지 않다. Z₂₅₆은 정수 mod 256 연산을 사용하고 2처럼 0이 아닌 원소에도 곱셈 역원이 없으므로 체가 아니다. GF(2⁸)는 기약다항식에 대한 다항식 연산을 사용하여 모든 비영 원소에 곱셈 역원이 존재한다.',['원소 수가 같아도 연산이 다름을 썼다.','Z₂₅₆의 비영 원소 반례를 들었다.','GF의 기약다항식과 역원을 설명했다.'],'원소 수만 보고 체 여부를 판단하지 않는다.'),
q('f4','gf','계산','AES의 다항식 나머지','AES의 m(x)=x⁸+x⁴+x³+x+1에서 바이트 80과 02의 곱을 구하시오. 수치는 모두 16진수이다.','80은 x⁷, 02는 x이므로 곱은 x⁸이다. m(x)로 나누면 x⁴+x³+x+1이 남는다. 비트 00011011, 16진수 1b이다.',['80·02를 다항식으로 해석했다.','x⁸을 기약다항식으로 줄였다.','나머지 1b를 구했다.'],'결과를 100으로 두거나 일반 정수 mod 256만 취하지 않는다.'),
q('f5','gf','계산','유한체 역원 검산','GF(2³), m(x)=x³+x+1에서 x+1의 역원이 x²+x임을 곱해서 확인하시오.','(x+1)(x²+x)=x³+x²+x²+x=x³+x이다. x³≡x+1이므로 결과는 1이다. 따라서 비영 원소 x+1의 곱셈 역원은 x²+x이다.',['중간 x² 항이 소거됨을 보였다.','기약다항식 나머지가 1임을 확인했다.'],'덧셈 역원과 곱셈 역원을 혼동하지 않는다.'),
q('d1','des','서술','DES 크기와 순서','DES의 평문 블록 길이, 유효 키 길이, 라운드 수를 쓰고 F 함수의 각 단계와 비트 길이를 순서대로 설명하시오.','블록 64비트, 유효 키 56비트, 16라운드 Feistel이다. F는 32비트 R을 48비트로 확장하고 48비트 라운드키와 XOR한다. 8개 S-box가 각 6→4비트로 변환해 32비트를 만들며 마지막 P 순열도 32비트이다.',['64·56·16을 맞혔다.','확장 32→48과 키 XOR를 썼다.','S-box 8개, 각 6→4와 P 순열을 썼다.'],'64비트 키 표기에는 패리티 8비트가 포함된다.'),
q('d2','des','증명','Feistel의 역방향','Lᵢ=Rᵢ₋₁, Rᵢ=Lᵢ₋₁⊕F(Rᵢ₋₁,Kᵢ)로 정의된 라운드의 역방향을 유도하고, F가 가역일 필요가 없는 이유를 설명하시오.','Rᵢ₋₁=Lᵢ이다. Rᵢ 식에 이를 넣고 XOR하면 Lᵢ₋₁=Rᵢ⊕F(Lᵢ,Kᵢ)이다. F의 역함수를 쓰지 않고 같은 F와 XOR만으로 이전 상태를 얻으므로 F가 가역일 필요가 없다.',['Rᵢ₋₁=Lᵢ를 얻었다.','Lᵢ₋₁=Rᵢ⊕F(Lᵢ,Kᵢ)를 얻었다.','F⁻¹이 불필요함을 설명했다.'],'XOR의 자기 역 성질을 이용한다.'),
q('d3','des','계산','DES S₁ 계산','DES S₁에 100111이 입력되었다. 행과 열을 구하고 아래 표에서 값을 읽어 4비트 출력으로 나타내시오. 행·열 번호는 0부터 시작한다.','바깥 비트 11은 행 3, 안쪽 비트 0011은 열 3이다. S₁[3][3]=2이므로 출력은 0010이다.',['바깥 비트로 행 3을 구했다.','안쪽 비트로 열 3을 구했다.','표에서 2를 읽고 0010으로 표현했다.'],'앞 2비트를 행으로 읽지 않는다.','des'),
q('d4','des','계산','Feistel 두 라운드','4비트 반쪽을 쓰는 교육용 Feistel이다. L₀=1010, R₀=1100, F(R₀,K₁)=0110, F(R₁,K₂)=0011이다. Lᵢ=Rᵢ₋₁, Rᵢ=Lᵢ₋₁⊕F(Rᵢ₋₁,Kᵢ)로 두 라운드의 상태를 구하시오.','L₁=1100, R₁=1010⊕0110=1100. L₂=1100, R₂=1100⊕0011=1111이다. 각 라운드에서 이전 R이 새 L로 이동한다.',['1라운드 L₁=1100, R₁=1100을 구했다.','2라운드 L₂=1100, R₂=1111을 구했다.','이전 상태를 기준으로 계산 과정을 썼다.'],'같은 라운드에서 갱신한 L을 XOR에 잘못 사용하지 않는다.'),
q('d5','des','서술','DES 키 스케줄','DES에서 64비트 키를 받아 48비트 라운드키 16개를 만드는 과정을 설명하고, 복호화 시 라운드키의 순서를 쓰시오.','PC-1로 패리티 8비트를 제외하여 56비트를 얻고 C,D를 28비트씩 나눈다. 각 라운드에서 왼쪽 순환 이동한 뒤 PC-2로 48비트를 고른다. 1·2·9·16라운드는 1비트, 나머지는 2비트 이동한다. 복호화는 K₁₆부터 K₁까지 역순으로 사용한다.',['64→56, 28+28을 썼다.','순환 이동과 PC-2의 48비트 출력을 썼다.','복호화 키 역순을 썼다.'],'키의 비트 순서를 뒤집는 것과 라운드키 사용 순서를 뒤집는 것은 다르다.'),
q('d6','des','비교','혼돈과 확산','블록암호에서 혼돈과 확산의 목적을 구별하고, AES의 SubBytes와 MixColumns가 주로 어떤 역할을 하는지 설명하시오.','혼돈은 키와 암호문의 관계를 복잡하게 만드는 성질이고 확산은 평문의 변화가 암호문의 여러 부분에 퍼지도록 만드는 성질이다. SubBytes의 비선형 치환은 혼돈에 기여하고 MixColumns는 열의 바이트를 혼합하여 확산에 기여한다. ShiftRows와 결합하여 열 사이로도 퍼진다.',['두 목적을 구분했다.','SubBytes를 비선형 치환과 연결했다.','MixColumns·ShiftRows를 확산과 연결했다.'],'확산을 “키를 길게 만든다”로 설명하지 않는다.'),
q('d7','des','비교','SPN과 Feistel','SPN과 Feistel의 차이를 가역성과 복호화 관점에서 설명하시오.','SPN은 일반적으로 가역적인 치환·순열/선형 변환으로 구성되며 복호화에는 각 단계의 역변환을 쓴다. Feistel은 반쪽을 유지하면서 F 출력과 XOR하므로 F 자체의 역함수 없이 역방향을 구성할 수 있다. DES는 Feistel, AES는 SPN 구조이다.',['SPN 역변환을 설명했다.','Feistel에서 F의 가역성이 불필요함을 썼다.','DES와 AES의 구조를 정확히 대응했다.'],'전체 블록암호가 가역이라는 사실은 두 구조 모두 같다.'),
q('s1','aes','암기·서술','AES의 크기','AES-128/192/256의 블록 길이, 라운드 수, 128비트 라운드키 개수를 각각 쓰고 초기 AddRoundKey와 최종 라운드의 특징을 설명하시오.','모두 블록 128비트이며 라운드는 10/12/14, 라운드키는 11/13/15개이다. 첫 라운드 이전에 초기 AddRoundKey를 수행하며 최종 라운드는 MixColumns를 생략한다.',['블록 128 고정과 10/12/14를 썼다.','11/13/15를 썼다.','초기 키 결합과 최종 MixColumns 생략을 설명했다.'],'AES-256의 블록을 256비트라고 쓰지 않는다.'),
q('s2','aes','계산','AES 상태와 ShiftRows','입력 바이트가 00 01 02 03 04 05 06 07 08 09 0a 0b 0c 0d 0e 0f이다. 열 우선으로 4×4 상태를 만든 뒤 ShiftRows만 적용한 상태를 행별로 쓰시오.','입력 행은 [00 04 08 0c], [01 05 09 0d], [02 06 0a 0e], [03 07 0b 0f]. ShiftRows 결과는 [00 04 08 0c], [05 09 0d 01], [0a 0e 02 06], [0f 03 07 0b]이다.',['입력을 열 우선으로 배치했다.','각 행을 왼쪽 0/1/2/3칸 이동했다.','최종 네 행을 정확히 썼다.'],'열을 이동하거나 첫 행부터 1칸 움직이지 않는다.'),
q('s3','aes','계산','AddRoundKey 검산','상태 바이트 앞 네 개가 00 11 22 33, 대응 키 바이트가 00 01 02 03이다. AddRoundKey 결과를 구하고 같은 키로 역변환되는 이유를 쓰시오.','바이트별 XOR이므로 00 10 20 30이다. (s⊕k)⊕k=s이고 k⊕k=0이므로 같은 키를 다시 XOR하면 원래 상태로 돌아온다.',['XOR 결과 00 10 20 30을 얻었다.','XOR의 자기 역 성질을 식으로 설명했다.'],'일반 덧셈을 사용하지 않는다.'),
q('s4','aes','계산','MixColumns 한 열','입력 열은 [db 13 53 45]ᵀ이다. MixColumns의 첫 출력 바이트를 계산하시오. 02·db=ad, 03·13=35를 사용해도 된다. 모든 수는 16진수이다.','첫 행 [02 03 01 01]을 곱하므로 ad⊕35⊕53⊕45이다. ad⊕35=98, 98⊕53=cb, cb⊕45=8e. 첫 출력은 8e이다.',['올바른 행렬 첫 행을 사용했다.','합이 XOR임을 적용했다.','최종 8e를 얻었다.'],'정수 곱셈·덧셈으로 계산하지 않는다.','aes'),
q('s5','aes','계산','SubBytes 테이블 읽기','AES S-box로 00과 53을 치환하시오. 행·열을 어떻게 정하는지 쓰고, 00이 역원 단계에서 어떻게 처리되는지 설명하시오.','상위 4비트를 행, 하위 4비트를 열로 읽는다. 00은 행0·열0에서 63, 53은 행5·열3에서 ed이다. 00은 GF 역원 단계에서 별도로 0으로 처리한 후 affine 변환을 적용하므로 S(00)=63이다.',['행·열 규칙을 썼다.','63과 ed를 읽었다.','0의 예외 처리를 설명했다.'],'DES의 바깥 비트 행 규칙을 AES에 적용하지 않는다.','aes'),
q('s6','aes','서술','두 라운드와 마지막 라운드','“AES-128의 앞 2라운드를 계산하라”는 문제에서 2라운드의 MixColumns를 생략해도 되는가? 처음부터 2라운드까지 수행할 단계와 이유를 쓰시오.','생략하면 안 된다. 초기 AddRoundKey 후 1라운드 SubBytes→ShiftRows→MixColumns→AddRoundKey, 2라운드도 같은 순서다. AES-128의 마지막 라운드는 10라운드이므로 앞 2라운드는 모두 일반 라운드이다. 별도 축소 구조를 명시한 문제는 그 정의를 따른다.',['생략 불가라고 판단했다.','초기 AddRoundKey와 네 단계 순서를 썼다.','실제 마지막이 10라운드임을 근거로 들었다.'],'“계산을 여기서 끝낸다”는 말이 “암호의 최종 라운드”라는 뜻은 아니다.'),
q('s7','aes','계산','키 확장 첫 word','AES-128에서 w₀=00010203, w₃=0c0d0e0f이다. RotWord(w₃)=0d0e0f0c, SubWord 결과=d7ab76fe, Rcon=01000000일 때 w₄를 계산하시오.','w₄=w₀⊕SubWord(RotWord(w₃))⊕Rcon. 00010203⊕d7ab76fe=d7aa74fd, 여기에 01000000을 XOR하면 d6aa74fd이다.',['세 항의 XOR 식을 썼다.','w₄=d6aa74fd를 얻었다.'],'Rcon을 모든 바이트에 같은 값으로 XOR하지 않는다.'),
q('s8','aes','계산','AES 앞 2라운드 종합','평문 00112233445566778899aabbccddeeff, 키 000102030405060708090a0b0c0d0e0f의 AES-128 앞 2라운드를 계산하시오. 라운드키 K₁=d6aa74fdd2af72fadaa678f1d6ab76fe, K₂=b692cf0b643dbdf1be9bc5006830b3fe가 주어진다. 제공된 S-box와 MixColumns 행렬을 사용하고 각 라운드 마지막 상태를 열 우선 바이트열로 쓰시오.','초기 AddRoundKey=00102030405060708090a0b0c0d0e0f0. 1R SubBytes=63cab7040953d051cd60e0e7ba70e18c; ShiftRows=6353e08c0960e104cd70b751bacad0e7; MixColumns=5f72641557f5bc92f7be3b291db9f91a; AddRoundKey=89d810e8855ace682d1843d8cb128fe4. 2R SubBytes=a761ca9b97be8b45d8ad1a611fc97369; ShiftRows=a7be1a6997ad739bd8c9ca451f618b61; MixColumns=ff87968431d86a51645151fa773ad009; AddRoundKey=4915598f55e5d7a0daca94fa1f0a63f7.',['초기 키 결합과 상태 배치를 정확히 했다.','1라운드 중간값과 최종 상태를 얻었다.','2라운드에서 MixColumns를 포함했다.','2라운드 최종 4915598f55e5d7a0daca94fa1f0a63f7을 얻었다.'],'각 바이트열은 열 우선이며 2라운드 결과는 전체 AES 암호문이 아니다.','aes'),
q('s9','aes','계산','ShiftRows의 역변환','ShiftRows 이후 상태가 행별로 [00 04 08 0c], [05 09 0d 01], [0a 0e 02 06], [0f 03 07 0b]이다. InvShiftRows를 적용하시오.','각 행을 오른쪽 0,1,2,3칸 이동한다. 결과는 [00 04 08 0c], [01 05 09 0d], [02 06 0a 0e], [03 07 0b 0f]이다.',['오른쪽 이동이라는 방향을 썼다.','행별 0/1/2/3칸 규칙과 최종 상태를 맞혔다.'],'복호화에서 다시 왼쪽으로 같은 횟수만큼 옮기지 않는다.'),
q('m1','modes','서술','ECB가 패턴을 남기는 이유','같은 키로 이미지 블록을 ECB로 암호화했을 때 반복 무늬가 드러날 수 있는 이유와 CBC가 이를 완화하는 원리를 설명하시오.','ECB는 동일 키 아래 동일 평문 블록을 항상 동일 암호문 블록으로 바꾼다. 따라서 블록 값 자체를 모르더라도 반복 여부가 보존된다. CBC는 이전 암호문을 평문과 XOR하고 첫 블록에는 IV를 사용하여 같은 평문 블록도 맥락에 따라 다른 입력으로 만든다.',['동일 평문→동일 암호문 관계를 썼다.','값의 노출과 반복 관계 노출을 구별했다.','CBC의 이전 암호문·IV 결합을 설명했다.'],'CBC라는 이름만으로 IV 조건이나 인증까지 보장되는 것은 아니다.'),
q('m2','modes','비교','CBC 병렬 처리','CBC 암호화는 순차 처리하지만 복호화는 병렬 처리할 수 있는 이유를 수식과 함께 설명하시오.','암호화 Cᵢ=Eₖ(Pᵢ⊕Cᵢ₋₁)는 직전 암호화 결과를 기다려야 한다. 복호화 Pᵢ=Dₖ(Cᵢ)⊕Cᵢ₋₁에서는 수신된 암호문들이 이미 주어져 Dₖ(Cᵢ)를 독립적으로 계산할 수 있다. 첫 블록의 C₀는 IV이다.',['암호화 식과 순차 의존성을 썼다.','복호화 식과 이전 암호문이 이미 주어짐을 썼다.'],'복호화에서 이전 평문을 기다린다고 착각하지 않는다.'),
q('m3','modes','비교','한 비트 전송 오류','암호문 Cᵢ의 한 비트가 전송 중 뒤집혔다. CBC와 CTR에서 복호화된 평문에 미치는 영향을 비교하시오.','CBC에서는 Dₖ(Cᵢ)가 변해 Pᵢ가 뒤섞이고, Pᵢ₊₁에서는 Cᵢ가 XOR 항이므로 대응 비트가 뒤집힌다. Pᵢ₊₂ 이후에는 전파되지 않는다. CTR에서는 키스트림과 XOR하므로 Pᵢ의 대응 비트만 뒤집힌다.',['CBC의 현재 블록 영향을 썼다.','CBC의 다음 블록 대응 비트와 이후 비전파를 썼다.','CTR의 대응 비트만 영향받음을 썼다.'],'오류 전파는 무결성 검증과 다르다.'),
q('m4','modes','서술','IV와 카운터 조건','CBC, OFB, CTR에서 초기값을 사용할 때 지켜야 할 조건을 비교하시오. CTR에서 일부 블록이 유실되어도 다른 블록을 복호화할 수 있는 조건도 설명하시오.','CBC IV는 예측 불가능해야 한다. OFB는 같은 키에서 IV를 반복하면 안 된다. CTR은 같은 키 아래 모든 카운터 입력이 서로 달라야 한다. CTR은 해당 블록의 카운터를 정확히 알면 다른 블록과 독립적으로 복호화할 수 있으므로 유실 후 항상 불가능한 것은 아니다.',['CBC의 예측 불가능한 IV를 썼다.','OFB IV·CTR 카운터의 중복 금지를 썼다.','CTR 카운터 위치를 알면 독립 복호화 가능함을 설명했다.'],'nonce만 다르면 된다고 쓰기 전에 전체 카운터 입력의 중복 여부를 고려한다.'),
q('m5','modes','계산','패딩이 필요한 이유','16바이트 블록에서 PKCS#7을 사용할 때 14바이트 메시지와 16바이트 메시지에 각각 어떤 패딩을 붙이는가? 패딩을 사용하는 목적도 설명하시오.','완전한 블록을 처리하는 모드에서 길이를 맞추고 원문과 패딩을 구별하기 위해 사용한다. 14바이트에는 02 02를 붙인다. 16바이트에는 16진수 10을 16개 붙여 새 블록을 추가한다.',['길이 정렬·제거의 모호성 방지 목적을 썼다.','14바이트에 02 02를 붙였다.','정렬된 입력에도 10을 16개 붙였다.'],'16진수 10은 십진수 16이다.'),
q('m6','modes','비교','CFB·OFB·CTR의 공통점과 차이','CFB, OFB, CTR에서 블록암호의 복호화 함수가 필요한가? OFB와 CTR의 병렬 처리 가능성 차이도 설명하시오.','세 모드 모두 Eₖ로 만든 값과 평문/암호문을 XOR하므로 블록암호 Dₖ는 필요하지 않다. OFB는 다음 키스트림 블록이 이전 출력에 의존해 생성이 순차적이다. CTR은 독립적인 카운터 입력마다 Eₖ를 계산해 병렬 생성할 수 있다.',['Dₖ 없이 Eₖ와 XOR를 사용함을 썼다.','OFB의 순차 의존성을 썼다.','CTR의 독립 카운터를 설명했다.'],'키스트림을 미리 계산할 수 있다는 것과 병렬 생성 가능성을 구별한다.'),
q('h1','hash','정의','세 저항성의 정의','역상 저항성, 제2역상 저항성, 충돌 저항성을 주어진 값과 찾아야 하는 값이 드러나도록 정의하시오.','역상: y가 주어질 때 H(x)=y인 x를 찾기 어렵다. 제2역상: x가 주어질 때 x′≠x이고 H(x′)=H(x)인 x′를 찾기 어렵다. 충돌: 서로 다른 임의의 x,x′에 대해 H(x)=H(x′)인 쌍을 찾기 어렵다.',['역상에서 y가 주어짐을 명시했다.','제2역상에서 특정 x가 고정됨과 x′≠x를 명시했다.','충돌에서 두 입력을 선택할 수 있음을 명시했다.'],'세 성질 모두 “해시를 역산하기 어렵다”로 뭉뚱그리지 않는다.'),
q('h2','hash','판단','해시 저항성의 함의 관계','“충돌 저항성이 깨지면 제2역상 저항성도 반드시 깨진다.” 이 명제가 맞는지 판단하고 올바른 방향의 관계를 설명하시오.','일반적으로 맞지 않는다. 임의의 충돌 쌍을 찾는 능력이 특정 메시지 x의 짝을 보장하지는 않는다. 반대로 제2역상을 찾을 수 있으면 주어진 x와 발견한 x′가 충돌 쌍이 되므로 충돌 저항성도 깨진다. 통상적 정의에서 충돌 저항성은 제2역상 저항성을 함의한다.',['원래 명제가 일반적으로 거짓임을 판단했다.','임의의 쌍과 고정된 메시지를 구별했다.','제2역상 파괴→충돌 파괴의 방향을 설명했다.'],'성질의 함의와 성질이 깨졌을 때의 함의 방향을 뒤집지 않는다.'),
q('h3','hash','계산','충돌 안전성과 출력 길이','이상적인 128비트 출력 해시의 일반적인 충돌 탐색량과 역상 탐색량을 쓰시오. 충돌 탐색에 대해 128비트 작업량을 목표로 한다면 출력은 적어도 몇 비트여야 하는가?','충돌 탐색량은 약 2⁶⁴, 역상 탐색량은 약 2¹²⁸이다. 충돌 작업량이 약 2¹²⁸이 되려면 출력 길이는 적어도 256비트여야 한다. 이는 이상적인 해시의 일반적인 탐색량이며 알고리즘의 구조적 약점까지 없다는 보증은 아니다.',['2⁶⁴와 2¹²⁸을 구별했다.','256비트를 도출했다.','이상적 모델의 일반적 탐색량이라는 전제를 썼다.'],'출력 비트 수를 그대로 충돌 보안 비트 수라고 하지 않는다.'),
q('h4','hash','유도','Birthday bound의 이유','n비트 해시에 서로 다른 q개 입력을 넣는다. 출력이 균일·독립적이라고 모델링할 때 충돌 확률의 근사식과 충돌을 찾는 데 필요한 입력 수의 차수를 설명하시오.','출력 공간 N=2ⁿ에서 모든 출력이 다를 확률은 ∏(1−i/N), i=0,…,q−1이다. 충돌 확률은 1−이 값이며 약 1−exp(−q(q−1)/(2N))이다. 쌍의 수가 약 q²/2이므로 q가 2ⁿᐟ² 규모가 되면 충돌 확률이 상수 수준이 된다. 50% 지점은 약 1.177×2ⁿᐟ²이다.',['출력 공간 2ⁿ과 입력 쌍 수를 연결했다.','충돌 확률 또는 비충돌 확률 식을 썼다.','입력 수 차수 2ⁿᐟ²를 도출했다.'],'작은 확률 근사 q²/(2N)를 모든 확률 영역에 정확한 식처럼 적용하지 않는다.'),
q('h5','hash','서술','반복 해시의 구조','Iterated hash가 임의 길이 메시지를 고정 길이 값으로 만드는 과정을 메시지 분할, 패딩, 초기값, 압축함수, 연결값을 사용해 설명하시오.','메시지를 패딩하여 일정 길이 블록 M₁,…,Mₜ로 나눈다. 고정 초기값 H₀에서 시작해 Hᵢ=f(Hᵢ₋₁,Mᵢ)를 순서대로 계산한다. 마지막 연결값을 다이제스트로 출력한다. 압축함수는 이전 연결값과 새 메시지 블록을 고정 길이 연결값으로 만들며, 길이 정보가 포함된 패딩은 경계를 명확히 한다.',['패딩·블록 분할을 설명했다.','초기값과 Hᵢ=f(Hᵢ₋₁,Mᵢ)를 썼다.','최종 고정 길이 출력을 설명했다.'],'반복 해시의 구조를 SHA-1 내부 80라운드와 혼동하지 않는다.'),
q('h6','hash','판별','해시 조건을 사례로 구별','① 다이제스트 y만 주어진다. ② 특정 문서 m이 이미 고정되어 있다. ③ 두 문서 모두 자유롭게 고를 수 있다. 같은 해시값을 갖는 입력을 찾기 어렵다는 성질을 각 경우에 대응시키시오.','① 역상 저항성 ② 제2역상 저항성 ③ 충돌 저항성이다. ②는 지정된 문서가 한쪽에 고정되고 ③은 양쪽을 고를 수 있다는 차이가 있다.',['세 성질을 정확히 대응했다.','②와 ③의 고정 조건 차이를 설명했다.'],'“둘 다 두 문서가 있으니까 충돌”이라고만 답하지 않는다.'),
q('h7','hash','서술','충돌은 없어야 하는가','임의 길이 메시지를 n비트로 줄이는 해시가 “충돌이 절대 없어야 안전하다”는 주장에 대해 설명하시오.','입력 공간이 출력 공간 2ⁿ보다 크면 비둘기집 원리에 의해 충돌은 반드시 존재한다. 충돌 저항성은 충돌이 존재하지 않는다는 뜻이 아니라 서로 다른 충돌 입력을 효율적으로 찾기 어렵다는 뜻이다.',['유한 출력 공간과 비둘기집 원리를 썼다.','존재와 계산 가능성을 구분했다.'],'암호학적 안전성을 수학적인 단사성과 동일시하지 않는다.'),
q('k1','mac','비교','MDC와 MAC','MDC와 MAC의 키 사용 및 제공하는 성질을 비교하시오. 공개 채널에서 메시지와 MDC를 함께 보내는 것만으로 충분하지 않은 이유도 쓰시오.','MDC는 키 없는 다이제스트로 신뢰 가능한 기준 해시가 있어야 무결성을 확인할 수 있다. 메시지와 다이제스트를 모두 바꿀 수 있으면 변조를 판별할 근거가 없다. MAC은 공유 비밀키로 태그를 생성하여 무결성과 메시지 근원 인증을 제공한다.',['MDC의 무키 특성을 썼다.','신뢰 가능한 기준 해시가 필요함을 설명했다.','MAC의 공유 키와 무결성·인증을 썼다.'],'해시값을 붙였다고 자동으로 송신자 인증이 되지 않는다.'),
q('k2','mac','서술','MAC 검증 과정','Alice와 Bob이 공유 키 k를 가지고 있다. 메시지 m에 MAC을 붙여 보내고 확인하는 절차를 설명하고, MAC이 제공하지 않는 성질 두 가지를 쓰시오.','Alice는 t=MACₖ(m)을 계산하여 m,t를 보낸다. Bob은 수신한 m′로 t′=MACₖ(m′)를 계산하고 t와 비교한다. MAC만으로는 메시지 기밀성이나 제3자에 대한 부인방지를 제공하지 않는다.',['태그 생성·전송을 썼다.','수신 메시지로 재계산·비교함을 썼다.','기밀성과 부인방지를 제공하지 않음을 썼다.'],'비밀키 k를 메시지와 함께 공개 전송한다고 쓰지 않는다.'),
q('k3','mac','서술','CBC-MAC 사용 조건','기본 CBC-MAC을 사용할 때 메시지 길이와 IV에 어떤 조건이 필요한지, 가변 길이 메시지에서는 어떻게 보완해야 하는지 설명하시오.','기본 CBC-MAC의 안전성은 고정 메시지 길이 같은 조건에 의존한다. 블록암호의 블록 크기가 고정이라는 사실만으로 충분하지 않다. 기본 IV는 고정 0이며 외부에서 임의 변경하게 두면 안 된다. 가변 길이는 검증된 길이 처리나 CMAC 등 적절한 표준 구성을 사용한다.',['고정 메시지 길이 조건을 설명했다.','고정 0 IV와 임의 변경 금지를 썼다.','가변 길이에 CMAC 등 보완을 제시했다.'],'CBC 암호화의 무작위 IV 방식을 그대로 적용하지 않는다.'),
q('k4','mac','분류','MAC의 두 계열','해시 기반 MAC과 블록암호 기반 MAC의 예를 각각 두 개 들고, 모든 MAC을 일반적인 키 없는 해시로 설명하면 왜 부정확한지 쓰시오.','해시 기반 예는 HMAC, NMAC이고 블록암호 기반 예는 CBC-MAC, CMAC이다. MAC은 비밀키를 필요로 하며 블록암호 기반 구성도 포함하므로 키 없는 해시 함수 자체와 같지 않다.',['해시 기반 예 두 개를 썼다.','블록암호 기반 예 두 개를 썼다.','공유 비밀키와 기반 구조 차이를 설명했다.'],'MAC의 “code”를 암호화된 원문과 같은 것으로 생각하지 않는다.'),
q('k5','mac','서술','HMAC의 안쪽과 바깥쪽','HMAC의 식을 쓰고, 해시 블록 크기보다 짧은 키와 긴 키를 어떻게 처리하는지 설명하시오.','H((K₀⊕opad)∥H((K₀⊕ipad)∥M))이다. 긴 키는 먼저 해시하여 줄이고, 블록 길이보다 짧은 키는 오른쪽에 0을 붙여 블록 크기에 맞춘다. 안쪽과 바깥쪽 해시에 서로 다른 pad를 사용한다.',['중첩 해시 식과 ipad·opad 위치를 썼다.','긴 키를 먼저 해시한다고 썼다.','짧은 키의 오른쪽에 0을 붙인다고 썼다.'],'짧은 키의 오른쪽에 0을 붙이는 순서를 확인한다.'),
q('k6','mac','비교','인증 암호가 필요한 이유','AES-CTR로 메시지를 암호화하면 그 자체로 무결성까지 보장되는가? CCM과 GCM이 어떤 요소를 조합하는지 설명하시오.','CTR은 기밀성을 위한 모드이며 그 자체로 변조 검증 태그를 제공하지 않는다. CCM은 CTR과 CBC-MAC, GCM은 CTR과 GHASH를 조합해 암호화와 인증을 함께 제공한다. 해당 모드의 nonce 조건도 지켜야 한다.',['CTR 단독의 인증 부재를 썼다.','CCM의 CTR+CBC-MAC을 썼다.','GCM의 CTR+GHASH를 썼다.'],'암호화되어 읽기 어렵다는 사실과 변조 탐지는 다르다.'),
q('r1','rsa','계산','CRT의 작은 예','x≡2 mod 3, x≡3 mod 5를 만족하는 x를 mod 15에서 구하고 해의 유일성 조건을 쓰시오.','x≡8 mod 15이다. 8 mod 3=2, 8 mod 5=3으로 검산한다. 법 3과 5가 서로소이므로 곱 15를 법으로 해가 유일하다.',['해 8을 구했다.','두 합동식을 검산했다.','법이 서로소라는 조건을 썼다.'],'정수 전체에서 해 하나뿐이라는 뜻이 아니다.'),
q('r2','rsa','계산','Euler φ 계산','φ(15), φ(16)을 구하고 2⁸ mod 15를 Euler 정리로 설명하시오.','φ(15)=(3−1)(5−1)=8, φ(16)=16−8=8이다. gcd(2,15)=1이므로 2^φ(15)=2⁸≡1 mod 15이다.',['두 φ 값 8을 구했다.','gcd(2,15)=1을 확인했다.','Euler 정리로 결과 1을 얻었다.'],'φ(mn)=φ(m)φ(n)은 m,n이 서로소일 때 적용한다.'),
q('r3','rsa','계산','Fermat로 지수 줄이기','3¹⁰⁰ mod 7을 구하고 적용한 정리의 전제를 쓰시오.','7은 소수이고 7∤3이므로 3⁶≡1 mod 7이다. 100=6×16+4이므로 3¹⁰⁰≡3⁴=81≡4 mod 7이다.',['소수 법과 서로소 전제를 확인했다.','100 mod 6=4로 줄였다.','결과 4를 얻었다.'],'법 7 대신 지수를 7로 나누지 않는다.'),
q('r4','rsa','서술','소수 판정의 한계','Fermat 소수 판정을 통과한 수를 반드시 소수라고 할 수 없는 이유와 Miller–Rabin의 오류 확률 전제를 설명하시오.','Fermat 합동식은 소수의 필요조건이지만 충분조건이 아니며 의사소수와 Carmichael 수가 존재한다. Miller–Rabin은 더 강한 조건을 사용하고 홀수 합성수에서 적절한 밑을 독립·균일하게 t번 고르면 거짓 통과 확률이 최대 4⁻ᵗ이다.',['통과가 소수의 증명이 아님을 썼다.','의사소수/Carmichael 한계를 언급했다.','Miller–Rabin의 전제와 4⁻ᵗ를 썼다.'],'Fermat 검사에 무조건 2⁻ᵗ 한계를 붙이지 않는다.'),
q('e1','extras','계산','EEA 보충','17의 mod 43 곱셈 역원을 유클리드 알고리즘과 역대입으로 구하시오.','43=2×17+9, 17=9+8, 9=8+1. 따라서 1=9−8=2×9−17=2×43−5×17. 역원은 −5 mod 43=38이며 17×38=646≡1 mod 43이다.',['나눗셈 과정을 썼다.','Bézout 등식 1=2×43−5×17을 얻었다.','역원 38을 검산했다.'],'Bézout 등식에서 역원에 해당하는 계수를 고르고 원래 합동식에 대입해 검산한다.'),
q('e2','extras','구별','취약 키와 준취약 키','DES 취약 키와 준취약 키 쌍을 만족하는 식으로 구별하시오. 실제 키 값 네 개는 쓰지 않아도 된다.','취약 키는 Eₖ(Eₖ(P))=P를 만족한다. 준취약 키 쌍 k₁,k₂는 Eₖ₁(Eₖ₂(P))=P를 만족한다. 같은 키를 두 번 쓰는 경우와 서로 짝이 되는 두 키를 쓰는 경우의 차이이다.',['취약 키 식을 썼다.','준취약 키 쌍의 식과 차이를 썼다.'],'취약 키의 실제 값 암기와 개념 이해를 구별한다.'),
q('e3','extras','서술','스트림 암호의 최소 개념','키스트림과 XOR로 암호화하는 원리를 설명하고, 같은 키스트림을 두 메시지에 재사용하면 왜 문제가 되는지 식으로 쓰시오.','C₁=P₁⊕S, C₂=P₂⊕S이다. C₁⊕C₂=P₁⊕P₂가 되어 키스트림이 소거되고 평문들 사이의 관계가 드러난다. 따라서 같은 키스트림을 반복 사용하지 않아야 한다.',['XOR 암호화식을 썼다.','키스트림 소거식과 정보 노출을 설명했다.'],'이 문제는 작은 수학적 원리 확인용이며 RC4 구현 암기는 요구하지 않는다.')
];
export const byId=Object.fromEntries(questions.map(q=>[q.id,q]));
export function shuffled(items,rng=Math.random){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
export function selectExam(mode,topic='all',rng=Math.random){
 if(mode==='full')return shuffled(Object.entries(blueprint).flatMap(([id,count])=>shuffled(questions.filter(q=>q.lesson===id),rng).slice(0,count)),rng).map(q=>q.id);
 const pool=questions.filter(q=>topic==='all'?lessons.find(l=>l.id===q.lesson).priority==='core':q.lesson===topic);
 return shuffled(pool,rng).slice(0,mode==='quick'?5:10).map(q=>q.id);
}
export function questionScore(question,grade){if(!Array.isArray(grade))return null;return grade.filter(Boolean).length/question.rubric.length;}
export function examScore(exam){const scores=exam.ids.map(id=>questionScore(byId[id],exam.grades?.[id]));return {graded:scores.filter(x=>x!==null).length,total:exam.ids.length,score:Math.round(scores.reduce((s,x)=>s+(x??0),0)/scores.length*100)};}
